// Studio's data as the backend sends it (0.1.0): TypeScript mirrors of the DTOs in
// src-tauri/src/dto.rs and src-tauri/src/studio/{prefs,spend,local_models}.rs, and of the media
// types in crates/agent/src/media (the Rust files are authoritative). Each name is the DTO's
// without "Dto" (`RefItem` mirrors `RefDto`), each field camelCase as serde writes it. A
// Rust `Option` is `| null` here: serde writes `null`, never leaves the field out.
// `fixtures/models.ts` (generated by a Rust test) holds typed literals of these, so a field
// serde names differently fails `npm run typecheck`.
import type { ErrorInfo, ImageInput } from "../../lib/types";

export type { ImageInput };

// ---- the media types (crates/agent/src/media) ---------------------------------------------

/** Pictures or video. */
export type MediaKind = "image" | "video";

/** Who makes the pictures and video. */
export type Company = "openrouter" | "openai" | "local";

/** What an added picture is for. The last three only a model on this computer takes: the
 *  picture to change (inpainting), its mask (its white areas change) and a control picture
 *  (edges or depth). */
export type RefRole = "reference" | "startFrame" | "endFrame" | "source" | "mask" | "control";

/** One value of a list field: the value sent (as the company lists it) and its name. */
export interface Choice {
  value: string | number;
  label: string;
}

/** The rules a custom `WxH` size must meet. */
export interface SizeRules {
  multipleOf: number;
  minRatio: number;
  maxRatio: number;
  maxSide: number;
  minPixels: number;
  maxPixels: number;
}

/** The kind of value a field takes, and its limits. */
export type ParamKind =
  | { type: "enum"; values: Choice[] }
  | { type: "range"; min: number; max: number; step?: number | null; unit?: string | null }
  | { type: "boolean" }
  | { type: "seed"; max: number }
  | { type: "images"; min: number; max: number; role: RefRole }
  | { type: "size"; rules: SizeRules; values: Choice[] }
  | { type: "text"; maxChars: number }
  | { type: "extra"; allowedKeys: string[] }
  /** The LoRAs a local model's run attaches (its value is a `LoraUse[]`): at most `max`, each
   *  strength from `weightMin` to `weightMax` by `weightStep`, `highNoise` only when the model
   *  has a high-noise part. */
  | {
      type: "loras";
      max: number;
      highNoise: boolean;
      weightMin: number;
      weightMax: number;
      weightStep: number;
      weightDefault: number;
    };

/** One LoRA a local run attaches: the value of its `loras` field is a list of these. */
export interface LoraUse {
  /** The LoRA's id (`Lora.id`). */
  id: string;
  weight: number;
  /** For the high-noise part of a model that has one. */
  highNoise: boolean;
}

/** What a field means on any model, so a value can be carried to another model. */
export type Canonical =
  | "shape"
  | "count"
  | "quality"
  | "resolution"
  | "length"
  | "sound"
  | "seed"
  | "references"
  | "startFrame"
  | "endFrame"
  | "size"
  | "format"
  | "background";

/** Where a field is shown: in front, or under Advanced. */
export type Layer = "simple" | "advanced";

/** Values another field must have for a field to apply. */
export interface Requires {
  key: string;
  values: unknown[];
}

/** One control a model offers; the webview draws every control from these. */
export interface ParamSpec {
  key: string;
  canonical: Canonical | null;
  label: string;
  help: string | null;
  layer: Layer;
  kind: ParamKind;
  /** What the company uses when the field is not sent. */
  companyDefault: unknown;
  /** The value Studio starts with, where it picks one. */
  initial: unknown;
  affectsPrice: boolean;
  requires: Requires | null;
}

/** One company that runs an OpenRouter picture model. */
export interface EndpointCompany {
  /** Where its extra settings go (`provider.options[<slug>]`). */
  slug: string;
  /** Its name in a request's routing. */
  tag: string;
  name: string;
  /** The extra settings it takes. */
  passthrough: string[];
}

/** Which companies may run an OpenRouter request. */
export interface Routing {
  order: string[];
  only: boolean;
  allowFallbacks: boolean;
  zdr: boolean;
}

/** The exact request a run would send, with the key removed. A local preview's body may
 *  carry `error` (a plain sentence) when the preview could not be built. */
export interface RequestPreview {
  /** The HTTP method (`run` for a run on this computer). */
  method: string;
  url: string;
  host: string;
  body: { [key: string]: unknown; error?: string };
}

// ---- models and endpoints ------------------------------------------------------------------

/** A model's price as the picker hints it (PriceHintDto). */
export interface PriceHint {
  unit: "image" | "second" | "token" | "unknown" | "free";
  low: number | null;
  high: number | null;
}

/** A picture or video model as Studio's picker shows it (MediaModelDto). */
export interface MediaModel {
  id: string;
  displayName: string;
  family: string;
  kind: MediaKind;
  acceptsImages: boolean;
  params: ParamSpec[];
  price: PriceHint;
  /** The price has a number (a run on this computer is free, which counts). */
  priceKnown: boolean;
  /** `null` on an OpenRouter picture: "price shown when picked". */
  priceFetchedAt: number | null;
  companies: EndpointCompany[];
  notes: string[];
  /** Why Studio cannot use the model, when it cannot. */
  usable: string | null;
  /** When the company added the model, in seconds since 1970. */
  created: number | null;
}

/** An endpoint that makes pictures or video, with the models of its saved lists. */
export interface StudioEndpoint {
  providerId: number;
  name: string;
  company: Company;
  host: string;
  cloud: boolean;
  hasKey: boolean;
  /** `null` when no lists are saved ("Get the list"). */
  fetchedAt: number | null;
  models: MediaModel[];
}

// ---- runs ---------------------------------------------------------------------------------

/** Where a run goes: an endpoint, or this computer. */
export type RunTarget = { endpoint: number } | "thisComputer";

/** A run's state. */
export type RunStatus =
  | "queued"
  | "sending"
  | "waiting"
  | "running"
  | "downloading"
  | "done"
  | "failed"
  | "blocked"
  | "cancelled"
  | "interrupted";

/** Why a run ended without its results. */
export interface RunError {
  code: string;
  message: string;
  nextStep: string;
  details: string;
  /** `null` when it is not known whether the run was charged. */
  charged: boolean | null;
  requestId: string | null;
  company: Company;
  /** Where a safety filter stopped it, when the company said. */
  stage: "prompt" | "output" | null;
}

/** One file a run made. */
export interface Output {
  id: string;
  runId: string;
  idx: number;
  mime: string;
  sizeBytes: number;
  width: number | null;
  height: number | null;
  durationMs: number | null;
  seed: number | null;
  starred: boolean;
  hasThumb: boolean;
  path: string;
}

/** An added picture of a run, as recorded (the mirror of RefDto). */
export interface RefItem {
  sha256: string;
  mime: string;
  sizeBytes: number;
  role: RefRole | null;
}

/** An added picture in a StartRequest. */
export interface RefInput {
  sha256: string;
  role: RefRole;
}

/** How long a local run takes, rounded as people read it. */
export interface Eta {
  lowMs: number;
  highMs: number;
  /** Measured on this computer (else the catalog's first guess). */
  measured: boolean;
  /** During a run: the time left. */
  leftMs: number | null;
}

/** Where a run on this computer is. */
export interface LocalRun {
  stage: "loading" | "readingPrompt" | "drawing" | "decoding" | "saving" | null;
  step: number | null;
  steps: number | null;
  picture: number | null;
  pictures: number | null;
  pass: number | null;
  passes: number | null;
  /** What a queued local run waits for. */
  waitingFor: "reply" | "studioJob" | "answer" | "chatModelLoading" | null;
  /** The path of the chat model unloaded to make room. */
  unloadedChat: string | null;
  retrying: boolean;
  /** No progress for 10 minutes. */
  stalled: boolean;
  device: string | null;
  engineBuild: number | null;
  elapsedMs: number | null;
  /** Its files are labelled as AI-made. */
  labelled: boolean;
  /** It runs beside the loaded chat model. */
  alongside: boolean;
  onProcessor: boolean;
}

/** A Studio run as the webview shows it (`studio-progress`, `studio_runs`, `studio_live`). */
export interface Run {
  id: string;
  /**
   * Which copy of a run is newest: one count for every run, taken by the backend just before
   * it reads the run, so of two copies (an event, a command's answer) the higher one is newer.
   */
  seq: number;
  kind: MediaKind;
  runsOn: "cloud" | "local";
  providerId: number | null;
  providerName: string;
  providerHost: string;
  /** The company OpenRouter ran it at, by name, when known. */
  upstream: string | null;
  model: string;
  modelLabel: string;
  prompt: string;
  params: Record<string, unknown>;
  extra: Record<string, unknown>;
  routing: Routing | null;
  refs: RefItem[];
  status: RunStatus;
  /** Studio is following the run now (queued, or its task is running). */
  watching: boolean;
  /** A video still not ready after the watch limit, no longer checked. */
  stale: boolean;
  remoteId: string | null;
  progress: number | null;
  estimateUsd: number | null;
  costUsd: number | null;
  error: RunError | null;
  createdAt: number;
  startedAt: number | null;
  finishedAt: number | null;
  outputs: Output[];
  /** Its place in its queue, from 1, while it waits for a free place. */
  queuePosition: number | null;
  eta: Eta | null;
  local: LocalRun | null;
}

// ---- estimates and starting a run ---------------------------------------------------------

/** The daily limit as it stands for a run. */
export interface Limit {
  limitUsd: number | null;
  spentTodayUsd: number;
  pendingUsd: number;
  wouldPass: boolean;
  /**
   * Why it would not pass: past the limit, or a price that is unknown with less than
   * `reserveUsd` of the limit left. `null` when it would pass.
   */
  refusal: "over" | "unknownNeedsReserve" | null;
  /** What a run whose price is unknown counts against the limit, in US dollars. */
  reserveUsd: number;
}

/** Why a cloud run asks before it is sent. */
export type ConfirmReason = "video" | "atLeast" | "unknownPrice";

/** Whether a local run fits this computer. */
export interface LocalEstimate {
  fit: "fits" | "slow" | "afterUnload" | "notHere";
  unloadChat: boolean;
  verySlow: boolean;
  over15Min: boolean;
  /** Why it does not fit, when `fit` is `notHere`. */
  reason: string | null;
}

/** What a run would cost and meet before it is sent. */
export interface Estimate {
  usd: number | null;
  reasons: ConfirmReason[];
  confirmAtUsd: number;
  limit: Limit;
  /** A plain sentence for each setting the model would refuse. */
  invalid: string[];
  eta: Eta | null;
  local: LocalEstimate | null;
}

/** A press of Create. */
export interface StartRequest {
  /** Made once per press, so the same press sent twice makes one run. */
  clientToken: string;
  target: RunTarget;
  kind: MediaKind;
  model: string;
  prompt: string;
  params: Record<string, unknown>;
  extra: Record<string, unknown>;
  refs: RefInput[];
  routing: Routing | null;
}

// ---- preferences, usage and the gallery ---------------------------------------------------

/** What happens when a local job does not fit beside the loaded chat model. */
export type GpuPolicy = "unload" | "ask" | "processor";

/** The model last used for pictures or for video. */
export interface ModelChoice {
  target: RunTarget;
  model: string;
}

/** A saved setup: a model and its settings under a name. */
export interface Setup {
  name: string;
  kind: MediaKind;
  target: RunTarget;
  model: string;
  params: Record<string, unknown>;
  extra: Record<string, unknown>;
  routing: Routing | null;
}

/** Settings → Studio. */
export interface StudioPrefs {
  lastModel: Partial<Record<MediaKind, ModelChoice>>;
  advancedOpen: boolean;
  confirmEveryVideo: boolean;
  confirmAtUsd: number;
  /** `null` when the limit is off. */
  dailyLimitUsd: number | null;
  setups: Setup[];
  /** `null` for the default folder. */
  galleryDir: string | null;
  gpuPolicy: GpuPolicy;
  reloadChatAfter: boolean;
  suggestionDismissed: boolean;
  /** Set only by `studio_accept_local_notice`. */
  localNoticeAcceptedAt: number | null;
  /** How the last model file from this computer was added; set only by `studio_import_model`. */
  lastImportMode: ImportMode | null;
}

/** A change to the preferences: only the fields sent change (`null` turns the limit off, or
 *  goes back to the default gallery folder). */
export type StudioPrefsPatch = Partial<Omit<StudioPrefs, "localNoticeAcceptedAt" | "lastImportMode">>;

/** Today's spending and the gallery's size. */
export interface Usage {
  spentTodayUsd: number;
  pendingUsd: number;
  limitUsd: number | null;
  folder: string;
  bytes: number;
  pictures: number;
  videos: number;
}

/** Which runs the gallery shows; every field left out does not filter. */
export interface RunsFilter {
  kind?: MediaKind | null;
  starred?: boolean;
  text?: string;
  model?: string | null;
  since?: number | null;
  until?: number | null;
}

/** A place in the gallery's order: the last run of a page. */
export interface RunsCursor {
  createdAt: number;
  id: string;
}

/** One page of the gallery's runs, newest first. */
export interface RunsPage {
  runs: Run[];
  /** `null` when this page is the last. */
  next: RunsCursor | null;
}

// ---- the Studio engine and Get local models -----------------------------------------------

/** The Studio engine on this computer. */
export interface EngineStatus {
  state: "builtIn" | "notInstalled" | "partial" | "downloading" | "installed" | "unavailable";
  /** The pinned build, as its release tag. */
  build: string;
  /** The Windows pack's download size; 0 when built in or unavailable. */
  downloadBytes: number;
  licenseName: string;
  licenseUrl: string;
  bytesDone: number | null;
}

/** The `studio-engine-progress` event. */
export interface EngineProgress {
  done: number;
  total: number;
  unpacking: boolean;
  finished: boolean;
  error: ErrorInfo | null;
}

/** What Get local models' header says about this computer. */
export interface HardwareLine {
  device: string;
  graphicsBytes: number | null;
  sharedMemory: boolean;
  ramBytes: number | null;
  freeDiskBytes: number | null;
}

/** A model licence. */
export interface Licence {
  id: string;
  name: string;
  url: string;
  /** The fingerprint supplied with the licence. */
  sha256: string;
  badge: "green" | "amber" | "red";
  /** What it allows for what you make; `withUseRules` (amber) is an OpenRAIL licence:
   *  commercial use allowed, with uses it forbids. */
  commercial: "yes" | "underRevenue" | "registration" | "withUseRules" | "unclear" | "no";
  revenueLimitUsd: number | null;
  plainWords: string;
  obligations: string[];
  excludedRegions?: string[];
}

/** How a gated repository is gated (also a search hit's `gated`). */
export type GateMode = "none" | "auto" | "manual";

/** How a model's Hugging Face repository is gated. */
export interface Gate {
  mode: GateMode;
  /** What the publisher collects when access is asked for. */
  collects: string[];
}

/** A model version as the Studio engine detects it (the backend's `SdVersion`): never shown
 *  as it is (`VERSION_NAME` names it). */
export type SdVersion =
  | "sd1"
  | "sd1-inpaint"
  | "sd1-pix2pix"
  | "sd1-tiny-unet"
  | "sd2"
  | "sd2-inpaint"
  | "sd2-tiny-unet"
  | "sdxs-512-ds"
  | "sdxs-09"
  | "sdxl"
  | "sdxl-inpaint"
  | "sdxl-pix2pix"
  | "sdxl-vega"
  | "sdxl-ssd1b"
  | "svd"
  | "sd3"
  | "flux"
  | "flux-fill"
  | "flux-controls"
  | "flex-2"
  | "chroma-radiance"
  | "wan2"
  | "wan2.2-i2v"
  | "wan2.2-ti2v"
  | "wan2.2-s2v"
  | "lingbot-video"
  | "qwen-image"
  | "qwen-image-layered"
  | "qwen-image-2.1"
  | "hunyuan-video"
  | "anima"
  | "flux2"
  | "flux2-klein"
  | "ltxav"
  | "minimax-h3"
  | "hidream-o1"
  | "z-image"
  | "boogu-image"
  | "ovis-image"
  | "ernie-image"
  | "lens"
  | "minit2i"
  | "longcat"
  | "pid"
  | "ideogram4"
  | "sefi-image"
  | "krea2"
  | "mage-flow"
  | "sensenova-u1.5"
  | "llada-image"
  | "pixart"
  | "ming-image"
  | "z-image-l2p"
  | "iris"
  | "flux3"
  | "moss-image"
  | "fibo2"
  | "chroma"
  | "p-h3-image"
  | "minimax-h3-image";

/** The slot a file fills in a model's set-up (`SLOT_LABEL` words it). */
export type PartRole =
  | "model"
  | "diffusion"
  | "high-noise-diffusion"
  | "uncond-diffusion"
  | "clip-l"
  | "clip-g"
  | "t5xxl"
  | "llm"
  | "llm-vision"
  | "clip-vision"
  | "tokenizer"
  | "vae"
  | "tae"
  | "audio-vae"
  | "audio-encoder"
  | "embeddings-connectors";

/** What a recipe makes (`KIND_WORD` words it). */
export type RecipeKind = "picture" | "pictureEdit" | "video";

/** A recipe a model can run with, as the Model type menu offers it; `name` is the recipe's
 *  own. */
export interface RecipeChoice {
  id: string;
  name: string;
  kind: RecipeKind;
}

/** Why Studio can't run a file (`FILE_LABEL.cannotRun` words it). */
export type CannotRunReason =
  | "lumina2"
  | "ltxVideo09"
  | "hunyuanVideo1"
  | "svd"
  | "unknownWeights"
  | "sharded"
  | "pickle"
  | "noSha"
  | "adapter"
  | "needsControlFrames"
  | "needsAudio"
  | "upscaler"
  | "folderModel"
  | "notThisEngine"
  | "ltx2";

/** Why a file of a repository was not read when it opened. */
export type NotReadReason = "needsToken" | "needsTerms" | "budget" | "failed";

/** What a file of a repository is, as its row says (`FILE_LABEL` words it). */
export type FileLabel =
  | {
      works: {
        version: SdVersion;
        recipe: string;
        kind: RecipeKind;
        part: "high" | "low" | null;
        parameters: number;
        folder: boolean;
      };
    }
  | { lora: { base: SdVersion | null } }
  | { extra: { role: PartRole } }
  | { cannotRun: { reason: CannotRunReason; version: SdVersion | null } }
  | { notRead: { reason: NotReadReason } };

/** What a repository offers: from its files' labels, or its name's hint. */
export type Verdict =
  | { works: { version: SdVersion; kind: RecipeKind } }
  | { lora: { base: SdVersion | null } }
  | { cannotRun: { reason: CannotRunReason; version: SdVersion | null } }
  | "unknown";

/** One file of a model. */
export interface Part {
  role: PartRole;
  /** `owner/name` on Hugging Face; empty for a file from this computer. */
  repo: string;
  /** Its path in the repository; for a file from this computer, where it is. */
  path: string;
  sizeBytes: number;
  /** Empty for a file from this computer. */
  licenceId: string;
  /** Its file is already in place: checked, not fetched. */
  alreadyHere: boolean;
  /** A file from this computer, used where it is. */
  local: boolean;
}

/** Where a slot's file comes from. */
export type PartSource =
  | "main"
  | "sibling"
  | "installed"
  | "repo"
  | "companion"
  | "chosen"
  | "embedded"
  | "folder"
  | "missing";

/** One slot of a set-up plan and its file (`null` when the main file carries it, or nothing
 *  fills it). */
export interface PlannedSlot {
  role: PartRole;
  required: boolean;
  source: PartSource;
  part: Part | null;
}

/** What setting a model up takes: its recipe, each slot's file, the licences, the sizes and
 *  its fit here. */
export interface SetupPlan {
  recipe: RecipeChoice;
  /** The recipes its version can run with, the default first. */
  recipes: RecipeChoice[];
  slots: PlannedSlot[];
  licences: Licence[];
  totalBytes: number;
  toFetchBytes: number;
  fit: LocalFit;
  /** Every slot it needs has a file. */
  canDownload: boolean;
  lowDisk: boolean;
  needsEngine: boolean;
  /** The recipe was never matched to the model (the person chose it). */
  untested: boolean;
}

/** Whether a model fits this computer at one size, and how long a run takes here. */
export interface LocalFit {
  word: "fits" | "slow" | "afterUnload" | "notHere";
  verdict: "green" | "yellow" | "red";
  reason: string | null;
  suggestion: string | null;
  /** `null` before anything was measured ("Time shown after your first run here"). */
  eta: Eta | null;
  /** Studio offers a cloud model. */
  verySlow: boolean;
  /** A video that would run on the processor (this computer runs models there): very slow. */
  videoOnProcessor: boolean;
}

/** A model of the recommended list. */
export interface LocalEntry {
  id: string;
  name: string;
  summary: string;
  publisher: string;
  kind: MediaKind;
  sizeBytes: number;
  /** The strictest licence of its parts. */
  licence: Licence;
  /** Every licence shown with the download. */
  licences: Licence[];
  gate: Gate;
  fit: LocalFit;
  recommended: boolean;
  installed: boolean;
  parts: Part[];
  toFetchBytes: number;
  needsEngine: boolean;
  lowDisk: boolean;
}

/** An installed picture or video model. */
export interface InstalledLocal {
  id: string;
  name: string;
  kind: MediaKind;
  sizeBytes: number;
  fit: LocalFit;
  /** As Studio's picker offers it: free, with its controls. */
  model: MediaModel;
  /** The recipe it runs with; `null` before it is set up (`needsSetup`). */
  recipe: RecipeChoice | null;
  /** The engine version its model file was detected as; `null` when none was. */
  version: SdVersion | null;
  /** Its recipe is not one its version runs, or its version is unknown (the person chose it):
   *  a run's settings line says "untested set-up". */
  untested: boolean;
  /** It has no recipe yet: *Set it up yourself* first. */
  needsSetup: boolean;
  /** Its recipe takes a high-noise part (a two-model video). */
  highNoise: boolean;
  /** Its recipe takes LoRAs. */
  takesLoras: boolean;
  /** The family of LoRAs it takes, when its version is known. */
  loraBase: SdVersion | null;
  /** Where it came from. */
  source: "catalog" | "search" | "import";
  /** A file from this computer used where it is: the person's own, never deleted with it. */
  inPlace: boolean;
}

/** Get local models. */
export interface LocalModels {
  hardware: HardwareLine;
  engine: EngineStatus;
  /** Newest first. */
  installed: InstalledLocal[];
  recommended: LocalEntry[];
  /** The entries that may not fit this computer: shown with the warning, never refused. */
  notHere: LocalEntry[];
  noticeAccepted: boolean;
  /** This computer runs models on the processor: a video is made there, very slowly. */
  videoOnProcessor: boolean;
  installedBytes: number;
  moreFit: number;
  /** The LoRAs, newest first. */
  loras: Lora[];
}

/** How a LoRA file stores its weights (the backend's `LoraFormat`): never shown. */
export type LoraFormat = "kohya" | "peft" | "lycoris" | "diff";

/** A LoRA Studio's engine can apply: downloaded from Hugging Face or added from this
 *  computer, kept in Studio's LoRA folder. */
export interface Lora {
  /** `hf:<owner>/<repo>:<path>` or `local:<SHA-256>`: what a draft attaches. Never shown. */
  id: string;
  /** Its file's name without the extension, as written. */
  name: string;
  /** The version of the models it was most likely made for; `null` when that cannot be told. */
  base: SdVersion | null;
  format: LoraFormat;
  sizeBytes: number;
  source: "search" | "import";
  /** The Hugging Face repository it was downloaded from; `null` when added from this computer. */
  repo: string | null;
  /** Its file is gone. */
  missing: boolean;
}

/** What a Hugging Face search looks for. */
export type SearchFilter = "pictures" | "video" | "loras";

/** A picture or video repository Hugging Face found. */
export interface LocalSearchHit {
  repo: string;
  author: string;
  downloads: number;
  likes: number;
  updatedAt: string | null;
  gated: GateMode;
  licenseLabel: string | null;
  /** Exact once its files were read (`exact`), else from its name. */
  verdict: Verdict;
  exact: boolean;
}

/** A Hugging Face search: one page, matching models first. */
export interface LocalSearchPage {
  items: LocalSearchHit[];
}

/** A file of a repository with what Studio found it is. */
export interface RepoFileView {
  path: string;
  sizeBytes: number;
  quant: string | null;
  label: FileLabel;
}

/** A main file of a searched repository that works in Studio, with its set-up plan. */
export interface LocalFileChoice {
  file: string;
  /** "Q4_K_M", or "fp16"/"fp32" for a diffusers folder; "" when its name says none. */
  quant: string;
  label: FileLabel;
  plan: SetupPlan;
  /** "Best for this computer". */
  best: boolean;
}

/** A searched repository at its latest commit, as Studio reads it. */
export interface LocalRepo {
  repo: string;
  commit: string;
  author: string;
  /** The model card's first paragraph. */
  summary: string | null;
  verdict: Verdict;
  /** One per quantisation of each model that works, largest set-up first. */
  files: LocalFileChoice[];
  loras: RepoFileView[];
  /** Every file Studio labelled. */
  fileViews: RepoFileView[];
  /** The repository's own licence. */
  licence: Licence | null;
  licences: Licence[];
  labelMismatch: string | null;
  gate: Gate;
  readFiles: number;
  unreadFiles: number;
}

/** A file Studio uses for one slot: of a Hugging Face repository, an installed model's, a
 *  file on this computer, or none. */
export type SlotFile =
  | { hub: { repo: string; commit: string; path: string } }
  | { installed: { genModelId: string; role: PartRole } }
  | { disk: { path: string } }
  | "none";

/** A file the person chose for one slot. */
export interface SlotOverride {
  role: PartRole;
  file: SlotFile;
}

/** The person's choices for a set-up: another recipe (`null` keeps the file's own), and files
 *  for some slots. */
export interface SetupChoice {
  recipe: string | null;
  overrides: SlotOverride[];
}

/** An installed model's files (*Set it up yourself*): its recipe (`null` before it has one),
 *  the recipes it can be set up as, and each slot with its file. */
export interface ModelFiles {
  genModelId: string;
  recipe: RecipeChoice | null;
  /** The recipes its version runs, the default first; for an untested set-up, or a model of no
   *  recipe yet, every recipe Studio runs, by kind and then name. */
  recipes: RecipeChoice[];
  /** In the recipe's slot order: its model file `main`, its other files `installed`. */
  slots: PlannedSlot[];
  /** The recipe is not one its version runs, or its version is unknown. */
  untested: boolean;
  /** Every slot its recipe needs has a file. */
  canRun: boolean;
}

/** What *Set it up yourself* did: the model's files as they are now, or as the download that
 *  brings the missing ones makes them (`downloadGroup`; the model keeps its old set-up until it
 *  is done). */
export interface SetModelFilesResult {
  files: ModelFiles;
  downloadGroup: string | null;
}

/** The model a local download, fit or set-up plan is for. */
export type LocalSource =
  | { catalog: { entryId: string } }
  | { search: { repo: string; commit: string; file: string } }
  | { installed: { genModelId: string } }
  | { disk: { path: string } };

// ---- adding a model file from this computer (Task S8) ----------------------------------------

/** How a model file from outside the models folder is added: copied into it, or used where it
 *  is. It is never moved. */
export type ImportMode = "copy" | "inPlace";

/** A model file from this computer, read (its header only) before it is added. */
export interface ImportInspection {
  /** Its canonical path, which `studioImportModel` takes. */
  path: string;
  name: string;
  sizeBytes: number;
  /** What it is (`FILE_LABEL` words it): a LoRA is added as one instead. */
  label: FileLabel;
  /** Its set-up when it works in Studio: its main file already here, and what it fetches. */
  plan: SetupPlan | null;
  /** The mode to offer first: the last one chosen, else copying. */
  lastMode: ImportMode;
  /** Inside the models folder: used where it is, without asking. */
  insideModels: boolean;
}

/** What an import did: the model added, or the download group that adds it once its other
 *  files are fetched. */
export interface ImportResult {
  genModelId: string | null;
  downloadGroup: string | null;
}

/** How far an import of the file at `path` is, at most every 250 ms and once at the end
 *  (`doneBytes === totalBytes`). */
export interface ImportProgress {
  path: string;
  /** Reading it through for its SHA-256, or copying it into the models folder. */
  stage: "hashing" | "copying";
  doneBytes: number;
  totalBytes: number;
}
